Çözümün tamamı:

```rust
use std::num::ParseIntError;

fn add_numbers(a: &str, b: &str) -> Result<i32, ParseIntError> {
    let x = a.parse::<i32>()?;
    let y = b.parse::<i32>()?;
    Ok(x + y)
}

fn main() {
    println!("{:?}", add_numbers("2", "3"));
}
```

